func WithPrAndIssueQueryParams(client *api.Client, baseRepo ghrepo.Interface, baseURL string, state IssueMetadataState, projectsV1Support gh.ProjectsV1Support) (string, error) {	u, err := url.Parse(baseURL)	if err != nil {		return "", err	}	q := u.Query()	if state.Title != "" {		q.Set("title", state.Title)	}	// We always want to send the body parameter, even if it's empty, to prevent the web interface from	// applying the default template. Since the user has the option to select a template in the terminal,	// assume that empty body here means that the user either skipped it or erased its contents.	q.Set("body", state.Body)	if len(state.Assignees) > 0 {		q.Set("assignees", strings.Join(state.Assignees, ","))	}	// Set a template parameter if no body parameter is provided e.g. Web Mode	if len(state.Template) > 0 && len(state.Body) == 0 {		q.Set("template", state.Template)	}	if len(state.Labels) > 0 {		q.Set("labels", strings.Join(state.Labels, ","))	}	if len(state.ProjectTitles) > 0 {		projectPaths, err := api.ProjectTitlesToPaths(client, baseRepo, state.ProjectTitles, projectsV1Support)		if err != nil {			return "", fmt.Errorf("could not add to project: %w", err)		}		q.Set("projects", strings.Join(projectPaths, ","))	}	if len(state.Milestones) > 0 {		q.Set("milestone", state.Milestones[0])	}
